1: import { IndependentTerminalApp } from './IndependentTerminalApp';
2: import gymBg from '../../assets/gym-background.jpg';
3: import React, { useState } from 'react';
4: import { useGym } from '../../context/GymContext';
5: import { FingerprintScanner } from './FingerprintScanner';
6: import { AccessHistory } from './AccessHistory';
7: import { getRandomMotivationalQuote } from '../../data/motivationalQuotes';
8: import { sounds } from '../../services/audio';
9: import confetti from 'canvas-confetti';
10: import { getGymAvatar } from '../../utils/genderAvatar';
11: import { 
12:   Zap, 
13:   Maximize2, 
14:   Minimize2,
15:   Search,
16:   Clock,
17:   ExternalLink,
18:   Users,
19:   Image,
20:   LogOut,
21:   Download
22: } from 'lucide-react';
23: 
24: export const TurnstileTerminal: React.FC = () => {
25:   const { verifyBiometricAccess, registerExit, members, accessLogs, activeBranch } = useGym();
26: 
27:   const [scanStatus, setScanStatus] = useState<'idle' | 'scanning' | 'granted' | 'denied'>('idle');
28:   const [currentQuote, setCurrentQuote] = useState<string>('');
29:   const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
30:   const [verifiedClient, setVerifiedClient] = useState<{
31:     name: string;
32:     avatarUrl?: string;
33:     planName?: string;
34:   } | null>(null);
35: 
36:   const [searchQuery, setSearchQuery] = useState('');
37:   const [isFullScreen, setIsFullScreen] = useState(false);
38:   const [bgImage, setBgImage] = useState<string>(() => {
39:     if (typeof window !== 'undefined' && localStorage.getItem('legends_terminal_bg_version') !== 'v7_fixed_bright_8k') {
40:       localStorage.setItem('legends_terminal_bg_version', 'v7_fixed_bright_8k');
41:       localStorage.setItem('legends_terminal_bg', gymBg);
42:       return gymBg;
43:     }
44:     return localStorage.getItem('legends_terminal_bg') || gymBg;
45:   });
46: 
47:   // Trigger simulated scan
48:   const executeScan = (identifier: string) => {
49:     if (scanStatus === 'scanning') return;
50:     sounds.unlock();
51:     sounds.playScanBlip();
52:     setScanStatus('scanning');
53:     setVerifiedClient(null);
54: 
55:     setTimeout(() => {
56:       const result = verifyBiometricAccess(identifier);
57:       
58:       if (result.client) {
59:         setVerifiedClient({
60:           name: result.client.fullName,
61:           avatarUrl: getGymAvatar(result.client.fullName, result.client.avatarUrl),
62:           planName: result.client.membership.planName,
63:         });
64:       } else {
65:         setVerifiedClient(null);
66:       }
67: 
68:       if (result.granted) {
69:         sounds.playAccessGranted();
70:         const quote = getRandomMotivationalQuote(currentQuote);
71:         setCurrentQuote(quote);
72:         try {
73:           confetti({
74:             particleCount: 40,
75:             spread: 65,
76:             origin: { y: 0.5, x: 0.35 },
77:             colors: ['#FFB800', '#10B981', '#F59E0B', '#FFFFFF'],
78:           });
79:         } catch {
80:           // ignore if canvas is not supported
81:         }
82:       } else {
83:         sounds.playAccessDenied();
84:       }
85: 
86:       setScanStatus(result.granted ? 'granted' : 'denied');
87: 
88:       // Return to idle after 4.5 seconds
89:       setTimeout(() => {
90:         setScanStatus('idle');
91:         setVerifiedClient(null);
92:       }, 4500);
93:     }, 1100);
94:   };
95: 
96:   // Default quick scan if user just clicks the fingerprint sensor directly
97:   const handleDirectPadClick = () => {
98:     // If there is a search query, use it; otherwise test with active member 1
99:     if (searchQuery.trim()) {
100:       executeScan(searchQuery.trim());
101:     } else {
102:       executeScan('MEM-001'); // Carlos Mendoza
103:     }
104:   };
105: 
106:   const toggleFullScreen = () => {
107:     if (!document.fullscreenElement) {
108:       document.documentElement.requestFullscreen().catch(() => {});
109:       setIsFullScreen(true);
110:     } else {
111:       document.exitFullscreen().catch(() => {});
112:       setIsFullScreen(false);
113:     }
114:   };
115: 
116:   
117:   // Modo Pantalla Completa: Cubre toda la pantalla al 100% y oculta todos los menús
118:   if (isFullScreen) {
119:     return (
120:       <div className="fixed inset-0 z-50 bg-black w-screen h-screen overflow-hidden">
121:         <IndependentTerminalApp 
122:           isEmbeddedFullScreen={true} 
123:           onExitFullScreen={() => {
124:             if (document.fullscreenElement) {
125:               document.exitFullscreen().catch(() => {});
126:             }
127:             setIsFullScreen(false);
128:           }} 
129:         />
130:       </div>
131:     );
132:   }
133: 
134:   return (
135:     <div className={`space-y-6 relative rounded-3xl overflow-hidden p-3 sm:p-5 ${isFullScreen ? 'p-6 min-h-screen' : ''}`}>
136:       
137:             
138: 
139:       {/* Real Gym Background Photo */}
140:       <div className="absolute inset-0 pointer-events-none z-0 overflow-hidden rounded-3xl">
141:         <img
142:           src={bgImage}
143:           alt="Fitness Legends Gym Background"
144:           style={{
145:             filter: 'brightness(1.04) contrast(1.06) saturate(1.06)',
146:             objectPosition: 'center center',
147:           }}
148:           className="w-full h-full object-cover object-center"
149:         />
150:         <div className="absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-black/20 pointer-events-none" />
151:         {/* Soft Eye-Care anti-glare shield so neon lights do not hurt the eyes */}
152:         <div className="absolute inset-0 bg-slate-950/20 backdrop-blur-[0.5px] pointer-events-none" />
153: 
154:       </div>
155: 
156:       {/* Top Banner / Mode Header */}
157:       <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-3 relative z-10">
158:         <div>
159:           <div className="flex items-center gap-2">
160:             <span className="w-2.5 h-2.5 rounded-full bg-emerald-400 animate-ping" />
161:             <h1 className="text-xl font-black text-white tracking-wide uppercase">
162:               Control de Acceso
163:             </h1>
164:             <span className="text-xs bg-amber-500/20 text-amber-400 border border-amber-500/30 px-2 py-0.5 rounded-md font-bold">
165:               Lector Activo
166:             </span>
167:           </div>
168:           <p className="text-sm text-gym-muted mt-1">
169:             Validación instantánea de huella digital y vigencia de cuota en el acceso principal.
170:           </p>
171:         </div>
172: 
173:         <div className="flex items-center gap-3 flex-wrap">
174:           {/* Live Occupancy Pill */}
175:           <div className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-gym-surface border border-gym-border text-xs">
176:             <Users className="w-3.5 h-3.5 text-emerald-400" />
177:             <span className="text-gym-muted">Aforo Sala:</span>
178:             <span className="font-bold text-white font-mono">{activeBranch.currentOccupancy} / {activeBranch.maxCapacity}</span>
179:             <span className="text-[10px] px-1.5 py-0.5 rounded bg-emerald-500/15 text-emerald-400 font-bold">
180:               {Math.round((activeBranch.currentOccupancy / activeBranch.maxCapacity) * 100)}%
181:             </span>
182:           </div>
183: 
184:           {/* Quick Exit Button */}
185:           <button
186:             onClick={() => registerExit()}
187:             className="flex items-center gap-1.5 px-3 py-2 rounded-xl bg-rose-500/10 hover:bg-rose-500/20 border border-rose-500/30 text-xs font-bold text-rose-400 hover:text-rose-300 transition-all shadow-sm"
188:             title="Registrar salida de un atleta y liberar aforo de sala"
189:           >
190:             <LogOut className="w-3.5 h-3.5" />
191:             <span>Registrar Salida</span>
192:           </button>
193: 
194:           <label
195:             className="flex items-center gap-1.5 px-3.5 py-2 rounded-xl bg-black/40 hover:bg-black/60 backdrop-blur-md border border-white/25 text-xs font-bold text-gray-100 hover:text-white cursor-pointer transition-all shadow-md group"
196:             title="Cambiar fotografía de fondo del gimnasio"
197:           >
198:             <Image className="w-4 h-4 text-amber-400 group-hover:scale-110 transition-transform" />
199:             <span>Cambiar Foto</span>
200:             <input
201:               type="file"
202:               accept="image/*"
203:               className="hidden"
204:               onChange={(e) => {
205:                 const file = e.target.files?.[0];
206:                 if (!file) return;
207:                 const reader = new FileReader();
208:                 reader.onload = (event) => {
209:                   const result = event.target?.result as string;
210:                   if (result) {
211:                     setBgImage(result);
212:                     try { localStorage.setItem('legends_terminal_bg', result); } catch {}
213:                   }
214:                 };
215:                 reader.readAsDataURL(file);
216:               }}
217:             />
218:           </label>
219: 
220:           <button
221:             onClick={() => setIsHistoryModalOpen(true)}
222:             className="flex items-center gap-2 px-3.5 py-2 rounded-xl bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/30 text-xs font-bold text-amber-400 hover:text-amber-300 transition-all shadow-sm group"
223:             title="Ver desglose detallado de accesos registrados"
224:           >
225:             <Clock className="w-4 h-4 text-amber-400 group-hover:rotate-12 transition-transform" />
226:             <span>Accesos</span>
227:             <span className="bg-amber-500/25 text-amber-300 px-2 py-0.5 rounded-full text-[11px] font-mono font-bold border border-amber-500/40">
228:               {accessLogs.length}
229:             </span>
230:           </button>
231: 
232:           <button
233:             onClick={() => window.open('?mode=terminal', '_blank', 'width=1180,height=840')}
234:             className="flex items-center gap-2 px-3.5 py-2 rounded-xl bg-gym-surface hover:bg-gym-border/80 border border-gym-border text-xs font-bold text-white transition-all shadow-sm"
235:             title="Abrir vista dedicada de Control de Acceso para equipo independiente"
236:           >
237:             <ExternalLink className="w-4 h-4 text-amber-400" />
238:             <span>Equipo Independiente</span>
239:           </button>
240: 
241:           {/* Download Windows Desktop App (.exe) */}
242:           <a
243:             href="https://github.com/Cristiansairec94/legends-gym/releases/latest/download/ControlDeAccesoLegends-Windows-x64.zip"
244:             target="_blank"
245:             rel="noopener noreferrer"
246:             className="flex items-center gap-2 px-3.5 py-2 rounded-xl bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/30 text-xs font-bold text-amber-400 hover:text-amber-300 transition-all shadow-sm"
247:             title="Descargar la aplicación de escritorio nativa para Windows (ControlDeAccesoLegends.exe)"
248:           >
249:             <Download className="w-4 h-4 text-amber-400" />
250:             <span>Descargar App Windows (.exe)</span>
251:           </a>
252: 
253:           <button
254:             onClick={toggleFullScreen}
255:             className="flex items-center gap-2 px-3 py-2 rounded-xl bg-gym-surface hover:bg-gym-surface/80 border border-gym-border text-xs font-semibold text-gray-200 transition-colors"
256:             title="Modo pantalla completa para recepción o kiosco"
257:           >
258:             {isFullScreen ? <Minimize2 className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
259:             <span>{isFullScreen ? 'Salir' : 'PANTALLA COMPLETA'}</span>
260:           </button>
261:         </div>
262:       </div>
263: 
264:       {/* Main Container: Biometric Terminal */}
265:       <div className="w-full space-y-5 relative z-10">
266:           
267:           {/* Hardware Sensor Simulator Box */}
268:           <div className="p-3 relative">
269:             <div className="flex items-center justify-between border-b border-gym-border pb-3 mb-2">
270:               <div className="flex items-center gap-2">
271:                 <Zap className="w-4 h-4 text-amber-400" />
272:                 <span className="text-xs font-bold uppercase tracking-wider text-gray-200">
273:                   Sensor Biométrico Óptico USB
274:                 </span>
275:               </div>
276:               <span className="text-[11px] font-mono text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded border border-emerald-500/20">
277:                 500 DPI • Online
278:               </span>
279:             </div>
280: 
281:             {/* Central Animated Scanner Pad */}
282:             <FingerprintScanner
283:               status={scanStatus}
284:               onScanClick={handleDirectPadClick}
285:               disabled={scanStatus === 'scanning'}
286:               motivationalQuote={currentQuote}
287:               clientPhoto={verifiedClient?.avatarUrl}
288:               clientName={verifiedClient?.name}
289:               planName={verifiedClient?.planName}
290:             />
291: 
292:             {/* Manual Client Biometric Search or Barcode Input */}
293:             <div className="mt-4 pt-4 border-t border-gym-border/80">
294:               <label className="text-xs font-semibold text-gym-muted block mb-1.5">
295:                 O buscar socio por nombre, cédula o ID:
296:               </label>
297:               <div className="flex gap-2">
298:                 <div className="relative flex-1">
299:                   <Search className="w-4 h-4 text-gym-muted absolute left-3 top-1/2 -translate-y-1/2" />
300:                   <input
301:                     type="text"
302:                     value={searchQuery}
303:                     onChange={(e) => setSearchQuery(e.target.value)}
304:                     onKeyDown={(e) => e.key === 'Enter' && searchQuery && executeScan(searchQuery)}
305:                     placeholder="Ej. Carlos Mendoza, MEM-001 o 45892011..."
306:                     className="w-full pl-9 pr-3 py-2 bg-slate-950/45 backdrop-blur-md rounded-xl border border-white/25 text-sm text-white placeholder-zinc-300 focus:outline-none focus:border-amber-400 focus:ring-2 focus:ring-amber-400/40 transition-colors shadow-inner"
307:                   />
308:                 </div>
309:                 <button
310:                   onClick={() => searchQuery && executeScan(searchQuery)}
311:                   disabled={!searchQuery || scanStatus === 'scanning'}
312:                   className="px-4 py-2 bg-amber-500 hover:bg-amber-400 disabled:opacity-40 text-black font-bold text-xs rounded-xl shadow-glow-gold transition-all"
313:                 >
314:                   Entrada
315:                 </button>
316:                 <button
317:                   onClick={() => {
318:                     const found = members.find(m => 
319:                       m.id.toLowerCase() === searchQuery.toLowerCase().trim() ||
320:                       m.documentId.toLowerCase() === searchQuery.toLowerCase().trim() ||
321:                       m.fullName.toLowerCase().includes(searchQuery.toLowerCase().trim())
322:                     );
323:                     registerExit(found?.id);
324:                     setSearchQuery('');
325:                   }}
326:                   disabled={!searchQuery}
327:                   className="px-3.5 py-2 bg-rose-500/15 hover:bg-rose-500/25 border border-rose-500/30 disabled:opacity-40 text-rose-400 font-bold text-xs rounded-xl transition-all"
328:                   title="Registrar salida para este socio"
329:                 >
330:                   Salida
331:                 </button>
332:               </div>
333:             </div>
334: 
335: 
336: 
337:             {/* Quick access history launcher */}
338:             <div className="mt-4 pt-3.5 border-t border-gym-border/80 flex items-center justify-between">
