135:         this.ctx = null;
136:         const unlock = () => {
137:           this.unlock();
138:           window.removeEventListener('pointerdown', unlock);
139:           window.removeEventListener('keydown', unlock);
140:         };
141:         window.addEventListener('pointerdown', unlock, { passive: true });
142:         window.addEventListener('keydown', unlock, { passive: true });
143:       }
144: 
145:       initCtx() {
146:         if (!this.ctx && typeof window !== 'undefined') {
147:           const AudioContext = window.AudioContext || window.webkitAudioContext;
148:           if (AudioContext) this.ctx = new AudioContext();
149:         }
150:       }
151: 
152:       unlock() {
153:         try {
154:           this.initCtx();
155:           if (this.ctx && this.ctx.state === 'suspended') {
156:             this.ctx.resume().catch(() => {});
157:           }
158:         } catch {}
159:       }
160: 
161:       
162:       playScanBlip() {
163:         this.unlock();
164:         if (!this.ctx) return;
165:         const now = this.ctx.currentTime;
166:         const osc = this.ctx.createOscillator();
167:         const gain = this.ctx.createGain();
168:         osc.type = 'sine';
169:         osc.frequency.setValueAtTime(880, now);
170:         osc.frequency.exponentialRampToValueAtTime(1760, now + 0.12);
171:         gain.gain.setValueAtTime(0.001, now);
172:         gain.gain.exponentialRampToValueAtTime(0.25, now + 0.02);
173:         gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
174:         osc.connect(gain);
175:         gain.connect(this.ctx.destination);
176:         osc.start(now);
177:         osc.stop(now + 0.12);
178:       }
179:       playAccessGranted() {
180:         this.unlock();
181:         if (!this.ctx) return;
182:         const now = this.ctx.currentTime;
183:         const osc1 = this.ctx.createOscillator();
184:         const osc2 = this.ctx.createOscillator();
185:         const gain = this.ctx.createGain();
186: 
187:         osc1.type = 'triangle';
188:         osc2.type = 'sine';
189:         osc1.frequency.setValueAtTime(523.25, now); // C5
190:         osc2.frequency.setValueAtTime(659.25, now); // E5
191:         osc1.frequency.exponentialRampToValueAtTime(1046.50, now + 0.22); // C6
192:         osc2.frequency.exponentialRampToValueAtTime(1318.51, now + 0.22); // E6
193: 
194:         gain.gain.setValueAtTime(0.001, now);
195:         gain.gain.exponentialRampToValueAtTime(0.35, now + 0.05);
196:         gain.gain.exponentialRampToValueAtTime(0.001, now + 0.45);
197: 
198:         osc1.connect(gain);
199:         osc2.connect(gain);
200:         gain.connect(this.ctx.destination);
201:         osc1.start(now);
202:         osc2.start(now);
203:         osc1.stop(now + 0.45);
204:         osc2.stop(now + 0.45);
205:       }
206: 
207:       playAccessDenied() {
208:         this.unlock();
209:         if (!this.ctx) return;
210:         const now = this.ctx.currentTime;
211:         const osc = this.ctx.createOscillator();
212:         const gain = this.ctx.createGain();
213:         osc.type = 'sawtooth';
214:         osc.frequency.setValueAtTime(220, now);
215:         osc.frequency.setValueAtTime(140, now + 0.15);
216: 
217:         gain.gain.setValueAtTime(0.001, now);
218:         gain.gain.exponentialRampToValueAtTime(0.4, now + 0.03);
219:         gain.gain.exponentialRampToValueAtTime(0.001, now + 0.38);
220: 
221:         osc.connect(gain);
222:         gain.connect(this.ctx.destination);
223:         osc.start(now);
224:         osc.stop(now + 0.38);
225:       }
226:     }
