const { app, BrowserWindow } = require('electron');
const path = require('path');

app.whenReady().then(() => {
  const win = new BrowserWindow({
    show: false,
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true
    }
  });

  win.webContents.on('console-message', (e, level, message, line, sourceId) => {
    console.log(`[RENDERER CONSOLE ${level}] ${message} (${sourceId}:${line})`);
  });

  win.webContents.on('did-fail-load', (e, code, desc, url) => {
    console.error(`[DID-FAIL-LOAD] ${code}: ${desc} on ${url}`);
  });

  const indexPath = path.join(__dirname, 'LEGENDS/dist/index.html');
  console.log('Loading:', indexPath);
  win.loadFile(indexPath, { query: { mode: 'main' } })
    .then(() => {
      console.log('File loaded into webContents, waiting 3s for renderer execution...');
      setTimeout(() => {
        app.quit();
      }, 3500);
    })
    .catch(err => {
      console.error('loadFile error:', err);
      app.quit();
    });
});

const { app, BrowserWindow } = require('electron');
const path = require('path');
const fs = require('fs');

const logFile = path.join(__dirname, 'diagnose.log');
function log(msg) {
  fs.appendFileSync(logFile, msg + '\n');
}

fs.writeFileSync(logFile, 'Starting diagnosis...\n');

app.whenReady().then(() => {
  const win = new BrowserWindow({
    show: false,
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true
    }
  });

  win.webContents.on('console-message', (e, level, message, line, sourceId) => {
    log(`[RENDERER CONSOLE ${level}] ${message} (${sourceId}:${line})`);
  });

  win.webContents.on('did-fail-load', (e, code, desc, url) => {
    log(`[DID-FAIL-LOAD] ${code}: ${desc} on ${url}`);
  });

  const indexPath = path.join(__dirname, 'LEGENDS/dist/index.html');
  log('Loading: ' + indexPath);
  win.loadFile(indexPath, { query: { mode: 'main' } })
    .then(() => {
      log('File loaded into webContents, waiting 3s for renderer execution...');
      setTimeout(() => {
        log('Finished test.');
        app.quit();
      }, 3500);
    })
    .catch(err => {
      log('loadFile error: ' + err.message);
      app.quit();
    });
});

const { app, BrowserWindow } = require('electron');
const path = require('path');
const fs = require('fs');

const logFile = path.join(__dirname, 'diagnose_packaged.log');
function log(msg) {
  fs.appendFileSync(logFile, msg + '\n');
}

fs.writeFileSync(logFile, 'Starting diagnosis for packaged app...\n');

app.whenReady().then(async () => {
  const win = new BrowserWindow({
    width: 1280,
    height: 800,
    show: false,
    backgroundColor: '#09090b',
    webPreferences: {
      preload: path.join(__dirname, 'LEGENDS/electron/preload.cjs'),
      nodeIntegration: false,
      contextIsolation: true
    }
  });

  win.webContents.on('console-message', (e, level, message, line, sourceId) => {
    log(`[RENDERER CONSOLE ${level}] ${message} (${sourceId}:${line})`);
  });

  win.webContents.on('did-fail-load', (e, code, desc, url) => {
    log(`[DID-FAIL-LOAD] ${code}: ${desc} on ${url}`);
  });

  const indexPath = path.join(__dirname, 'LEGENDS/release/FITNESS_LEGENDS_TERMINAL-win32-x64/resources/app/dist/index.html');
  log('Loading packaged indexPath: ' + indexPath);

  try {
    await win.loadFile(indexPath, { query: { mode: 'main' } });
    log('Load completed. Waiting 4s...');
    setTimeout(async () => {
      try {
        const image = await win.capturePage();
        fs.writeFileSync(path.join(__dirname, 'diagnose_screen.png'), image.toPNG());
        log('Screen captured to diagnose_screen.png, dimensions: ' + image.getSize().width + 'x' + image.getSize().height);
      } catch (err) {
        log('capturePage error: ' + err.message);
      }
      app.quit();
    }, 4000);
  } catch (err) {
    log('loadFile error: ' + err.message);
    app.quit();
  }
});

