const { app, BrowserWindow } = require('electron');
const path = require('path');
const fs = require('fs');

const logFile = path.join(__dirname, 'diagnose_authenticated.log');
function log(msg) {
  fs.appendFileSync(logFile, msg + '\n');
}

fs.writeFileSync(logFile, 'Starting diagnosis for authenticated state...\n');

app.whenReady().then(async () => {
  const win = new BrowserWindow({
    width: 1280,
    height: 800,
    show: false,
    backgroundColor: '#09090b',
    webPreferences: {
      preload: path.join(__dirname, 'LEGENDS/electron/preload.cjs'),
      nodeIntegration: false,
      contextIsolation: true
    }
  });

  win.webContents.on('console-message', (e, level, message, line, sourceId) => {
    log(`[RENDERER CONSOLE ${level}] ${message} (${sourceId}:${line})`);
  });

  win.webContents.on('did-fail-load', (e, code, desc, url) => {
    log(`[DID-FAIL-LOAD] ${code}: ${desc} on ${url}`);
  });

  const indexPath = path.join(__dirname, 'LEGENDS/release/FITNESS_LEGENDS_TERMINAL-win32-x64/resources/app/dist/index.html');
  log('Loading packaged indexPath: ' + indexPath);

  try {
    await win.loadFile(indexPath, { query: { mode: 'main' } });

    // Inject login and test each tab!
    const testResult = await win.webContents.executeJavaScript(`
      new Promise((resolve) => {
        try {
          // Check what is in localStorage right now
          const keys = Object.keys(localStorage);
          console.log('Existing localStorage keys:', JSON.stringify(keys));

          // Let's inspect if there are errors or try logging in
          // Try clicking the first employee
          const adminBtn = document.querySelector('button, div');
          resolve({ status: 'ok', keys });
        } catch (err) {
          resolve({ status: 'error', error: err.message, stack: err.stack });
        }
      });
    `);
    log('Initial state: ' + JSON.stringify(testResult));

    // Now let's try logging in using the UI or calling login
    const loginTest = await win.webContents.executeJavaScript(`
      new Promise((resolve) => {
        try {
          // Look for Roberto Garza Vega or click on employee button
          const empCards = Array.from(document.querySelectorAll('*')).filter(el => el.textContent && el.textContent.includes('Roberto Garza Vega'));
          console.log('Found empCards:', empCards.length);
          if (empCards.length > 0) {
            empCards[0].click();
          }
          setTimeout(() => {
            // Find password input
            const pwdInput = document.querySelector('input[type="password"]');
            if (pwdInput) {
              pwdInput.value = '1234';
              pwdInput.dispatchEvent(new Event('input', { bubbles: true }));
              const submitBtn = document.querySelector('button[type="submit"]');
              if (submitBtn) {
                submitBtn.click();
                console.log('Clicked submit button!');
              }
            }
            resolve('submitted');
          }, 500);
        } catch (err) {
          resolve('error: ' + err.message);
        }
      });
    `);
    log('Login attempt: ' + loginTest);

    setTimeout(async () => {
      try {
        const image = await win.capturePage();
        fs.writeFileSync(path.join(__dirname, 'diagnose_after_login.png'), image.toPNG());
        log('Captured after login screen: ' + image.getSize().width + 'x' + image.getSize().height);
      } catch (err) {
        log('Capture error: ' + err.message);
      }
      app.quit();
    }, 4000);

  } catch (err) {
    log('loadFile error: ' + err.message);
    app.quit();
  }
});

