const { app, BrowserWindow } = require('electron');
const path = require('path');
const fs = require('fs');

const logFile = path.join(__dirname, 'diagnose_login_roberto.log');
function log(msg) {
  fs.appendFileSync(logFile, msg + '\n');
}

fs.writeFileSync(logFile, 'Testing login with Roberto...\n');

app.whenReady().then(async () => {
  const win = new BrowserWindow({
    width: 1280,
    height: 800,
    show: false,
    backgroundColor: '#09090b',
    webPreferences: {
      preload: path.join(__dirname, 'LEGENDS/electron/preload.cjs'),
      nodeIntegration: false,
      contextIsolation: true
    }
  });

  win.webContents.on('console-message', (e, level, message, line, sourceId) => {
    log(`[RENDERER CONSOLE ${level}] ${message} (${sourceId}:${line})`);
  });

  win.webContents.on('did-fail-load', (e, code, desc, url) => {
    log(`[DID-FAIL-LOAD] ${code}: ${desc} on ${url}`);
  });

  const indexPath = path.join(__dirname, 'LEGENDS/release/FITNESS_LEGENDS_TERMINAL-win32-x64/resources/app/dist/index.html');
  await win.loadFile(indexPath, { query: { mode: 'main' } });

  // Execute login directly with evaluate
  const res = await win.webContents.executeJavaScript(`
    new Promise((resolve) => {
      try {
        // Find inputs
        const inputs = document.querySelectorAll('input');
        console.log('Total inputs:', inputs.length);
        const emailInput = document.querySelector('input[type="text"], input:not([type="password"])');
        const passInput = document.querySelector('input[type="password"]');

        if (emailInput && passInput) {
          emailInput.value = 'admin.roberto';
          emailInput.dispatchEvent(new Event('input', { bubbles: true }));
          passInput.value = 'admin123';
          passInput.dispatchEvent(new Event('input', { bubbles: true }));

          setTimeout(() => {
            const form = document.querySelector('form');
            if (form) {
              form.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
              console.log('Form submitted!');
            }
            resolve('submitted with admin.roberto / admin123');
          }, 300);
        } else {
          resolve('inputs not found');
        }
      } catch (err) {
        resolve('Error: ' + err.message);
      }
    });
  `);

  log('Result: ' + res);

  setTimeout(async () => {
    try {
      const pageText = await win.webContents.executeJavaScript('document.body.innerText');
      log('Page text after login:\n' + pageText.substring(0, 500));
      const image = await win.capturePage();
      fs.writeFileSync(path.join(__dirname, 'diagnose_after_roberto_login.png'), image.toPNG());
      log('Captured screen: ' + image.getSize().width + 'x' + image.getSize().height);
    } catch (err) {
      log('Error getting page text: ' + err.message);
    }
    app.quit();
  }, 4000);
});

